import json

# Load all demo pairs
with open("/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/held-out-8/play/users/u078/system/state/workspace/programs/task-0578daba.json", "r") as f:
    demos = json.load(f)

print("Analyzing fill value pattern:")
for i, demo in enumerate(demos):
    inp = demo["input"]
    out = demo["output"]

    # Find unique non-zero value in input
    nonzero = set(v for row in inp for v in row if v != 0)
    unique_val = list(nonzero)[0]

    # Find non-zero value in output (the "fill" value)
    nonzero_out = set(v for row in out for v in row if v != 0)
    fill_val = list(nonzero_out)[0] if nonzero_out else None

    print(f"Demo {i+1}: unique_in={unique_val}, fill_out={fill_val}")

    # Let's check ratios
    if unique_val != 0 and fill_val != 0:
        ratio = unique_val / fill_val
        print(f"  ratio: {unique_val}/fill={fill_val} = {ratio}")

    # Try different modulus values
    for mod in range(2, 10):
        try_r = unique_val % mod
        # What operation gets us from try_r to fill_val?
        for op in ['-', '+', '*', '/']:
            if op == '*':
                result = try_r * unique_val if try_r != 0 else fill_val
            elif op == '/':
                result = unique_val / try_r if try_r != 0 else 0
            elif op == '-':
                result = unique_val - try_r
            elif op == '+':
                result = unique_val + try_r

            if result == fill_val and result != 0:
                print(f"  mod={mod}: {unique_val}%{mod} = {try_r}, then op={op} = {result}")

